arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H 'Content-Type: application/json' -d '{"token":"***","types":"public_channel","limit":1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d)
else:
    for c in d['channels']:
        if 'launch' in c['name']:
            print(c['id'], c['name'])
"

